  let settings = Object.assign({}, DEFAULTS, GM_getValue('gk_settings', {}));
  settings.usageStats = settings.usageStats || {};
  settings.recentCommands = Array.isArray(settings.recentCommands) ? settings.recentCommands : [];
  settings.pinnedBundles = Array.isArray(settings.pinnedBundles) ? settings.pinnedBundles : [...DEFAULT_BUNDLE_PINS];
  let paletteOpen = false;
